fun {N : ℕ} {W : Type u_1} (f g : Fin N → W) (τ : RiffleLowerV2.Permutation N) (hτ : ∀ (i : Fin N), f (τ i) = g i) =>
  { toFun := fun (ρ : RiffleLowerV2.Model.KeyAssignmentFiber f g) => ⟨(Equiv.symm τ).trans ↑ρ, ⋯⟩,
    invFun := fun (ρ : RiffleLowerV2.Model.KeyStabilizer f) => ⟨Equiv.trans τ ↑ρ, ⋯⟩, left_inv := ⋯, right_inv := ⋯ }

fun {k N K : ℕ} (cuts : TimeProfile.Cuts k N K) (j : Fin K) (σ : RiffleLowerV2.Permutation N) =>
  { toFun := RiffleLowerV2.Model.columnRelabel cuts j σ,
    invFun := RiffleLowerV2.Model.columnRelabel cuts j (Equiv.symm σ), left_inv := ⋯, right_inv := ⋯ }

fun {N : ℕ} (s : RiffleLowerV2.Permutation N) =>
  { toFun := fun (ρ : RiffleLowerV2.Permutation N) => Equiv.trans s (Equiv.symm ρ),
    invFun := fun (π : RiffleLowerV2.Permutation N) => (Equiv.symm π).trans s, left_inv := ⋯, right_inv := ⋯ }
